99	/*******************************************************************************
100	 *
101	 * Function         bnep_connect_ind
102	 *
103	 * Description      This function handles an inbound connection indication
104	 *                  from L2CAP. This is the case where we are acting as a
105	 *                  server.
106	 *
107	 * Returns          void
108	 *
109	 ******************************************************************************/
110	static void bnep_connect_ind(const RawAddress& bd_addr, uint16_t l2cap_cid,
111	                             UNUSED_ATTR uint16_t psm, uint8_t l2cap_id) {
112	  tBNEP_CONN* p_bcb = bnepu_find_bcb_by_bd_addr(bd_addr);
113	
114	  /* If we are not acting as server, or already have a connection, or have */
115	  /* no more resources to handle the connection, reject the connection.    */
116	  if (!(bnep_cb.profile_registered) || (p_bcb) ||
117	      ((p_bcb = bnepu_allocate_bcb(bd_addr)) == NULL)) {
118	    L2CA_DisconnectReq(l2cap_cid);
119	    return;
120	  }
121	
122	  /* Transition to the next appropriate state, waiting for config setup. */
123	  p_bcb->con_state = BNEP_STATE_CFG_SETUP;
124	
125	  /* Save the L2CAP Channel ID. */
126	  p_bcb->l2cap_cid = l2cap_cid;
127	
128	  /* Start timer waiting for config setup */
129	  alarm_set_on_mloop(p_bcb->conn_timer, BNEP_CONN_TIMEOUT_MS,
130	                     bnep_conn_timer_timeout, p_bcb);
131	
132	  BNEP_TRACE_EVENT("BNEP - Rcvd L2CAP conn ind, CID: 0x%x", p_bcb->l2cap_cid);
133	}
