135	static void bnep_on_l2cap_error(uint16_t l2cap_cid, uint16_t result) {
136	  tBNEP_CONN* p_bcb = bnepu_find_bcb_by_cid(l2cap_cid);
137	  if (p_bcb == nullptr) return;
138	
139	  /* Tell the upper layer, if there is a callback */
140	  if ((p_bcb->con_flags & BNEP_FLAGS_IS_ORIG) && (bnep_cb.p_conn_state_cb)) {
141	    (*bnep_cb.p_conn_state_cb)(p_bcb->handle, p_bcb->rem_bda, BNEP_CONN_FAILED,
142	                               false);
143	  }
144	
145	  L2CA_DisconnectReq(p_bcb->l2cap_cid);
146	
147	  bnepu_release_bcb(p_bcb);
148	}
