150	/*******************************************************************************
151	 *
152	 * Function         bnep_connect_cfm
153	 *
154	 * Description      This function handles the connect confirm events
155	 *                  from L2CAP. This is the case when we are acting as a
156	 *                  client and have sent a connect request.
157	 *
158	 * Returns          void
159	 *
160	 ******************************************************************************/
161	static void bnep_connect_cfm(uint16_t l2cap_cid, uint16_t result) {
162	  tBNEP_CONN* p_bcb;
163	
164	  /* Find CCB based on CID */
165	  p_bcb = bnepu_find_bcb_by_cid(l2cap_cid);
166	  if (p_bcb == NULL) {
167	    BNEP_TRACE_WARNING("BNEP - Rcvd conn cnf for unknown CID 0x%x", l2cap_cid);
168	    return;
169	  }
170	
171	  /* If the connection response contains success status, then */
172	  /* Transition to the next state and startup the timer.      */
173	  if ((result == L2CAP_CONN_OK) &&
174	      (p_bcb->con_state == BNEP_STATE_CONN_START)) {
175	    p_bcb->con_state = BNEP_STATE_CFG_SETUP;
176	
177	    /* Start timer waiting for config results */
178	    alarm_set_on_mloop(p_bcb->conn_timer, BNEP_CONN_TIMEOUT_MS,
179	                       bnep_conn_timer_timeout, p_bcb);
180	
181	    BNEP_TRACE_EVENT("BNEP - got conn cnf, sent cfg req, CID: 0x%x",
182	                     p_bcb->l2cap_cid);
183	  } else {
184	    LOG(ERROR) << __func__ << ": invoked with non OK status";
185	  }
186	}
