188	/*******************************************************************************
189	 *
190	 * Function         bnep_config_cfm
191	 *
192	 * Description      This function processes the L2CAP configuration confirmation
193	 *                  event.
194	 *
195	 * Returns          void
196	 *
197	 ******************************************************************************/
198	static void bnep_config_cfm(uint16_t l2cap_cid, uint16_t initiator,
199	                            tL2CAP_CFG_INFO* p_cfg) {
200	  tBNEP_CONN* p_bcb;
201	
202	  BNEP_TRACE_EVENT("BNEP - Rcvd cfg cfm, CID: 0x%x", l2cap_cid);
203	
204	  /* Find CCB based on CID */
205	  p_bcb = bnepu_find_bcb_by_cid(l2cap_cid);
206	  if (p_bcb == NULL) {
207	    BNEP_TRACE_WARNING("BNEP - Rcvd L2CAP cfg ind, unknown CID: 0x%x",
208	                       l2cap_cid);
209	    return;
210	  }
211	
212	  /* For now, always accept configuration from the other side */
213	  p_bcb->con_state = BNEP_STATE_SEC_CHECKING;
214	
215	  /* Start timer waiting for setup or response */
216	  alarm_set_on_mloop(p_bcb->conn_timer, BNEP_HOST_TIMEOUT_MS,
217	                     bnep_conn_timer_timeout, p_bcb);
218	
219	  if (p_bcb->con_flags & BNEP_FLAGS_IS_ORIG) {
220	    bnep_sec_check_complete(&p_bcb->rem_bda, BT_TRANSPORT_BR_EDR, p_bcb);
221	  }
222	}
