224	/*******************************************************************************
225	 *
226	 * Function         bnep_disconnect_ind
227	 *
228	 * Description      This function handles a disconnect event from L2CAP. If
229	 *                  requested to, we ack the disconnect before dropping the CCB
230	 *
231	 * Returns          void
232	 *
233	 ******************************************************************************/
234	static void bnep_disconnect_ind(uint16_t l2cap_cid, bool ack_needed) {
235	  tBNEP_CONN* p_bcb;
236	
237	  /* Find CCB based on CID */
238	  p_bcb = bnepu_find_bcb_by_cid(l2cap_cid);
239	  if (p_bcb == NULL) {
240	    BNEP_TRACE_WARNING("BNEP - Rcvd L2CAP disc, unknown CID: 0x%x", l2cap_cid);
241	    return;
242	  }
243	
244	  BNEP_TRACE_EVENT("BNEP - Rcvd L2CAP disc, CID: 0x%x", l2cap_cid);
245	
246	  /* Tell the user if there is a callback */
247	  if (p_bcb->con_state == BNEP_STATE_CONNECTED) {
248	    if (bnep_cb.p_conn_state_cb)
249	      (*bnep_cb.p_conn_state_cb)(p_bcb->handle, p_bcb->rem_bda,
250	                                 BNEP_CONN_DISCONNECTED, false);
251	  } else {
252	    if ((bnep_cb.p_conn_state_cb) &&
253	        ((p_bcb->con_flags & BNEP_FLAGS_IS_ORIG) ||
254	         (p_bcb->con_flags & BNEP_FLAGS_CONN_COMPLETED)))
255	      (*bnep_cb.p_conn_state_cb)(p_bcb->handle, p_bcb->rem_bda,
256	                                 BNEP_CONN_FAILED, false);
257	  }
258	
259	  bnepu_release_bcb(p_bcb);
260	}
