262	/*******************************************************************************
263	 *
264	 * Function         bnep_congestion_ind
265	 *
266	 * Description      This is a callback function called by L2CAP when
267	 *                  congestion status changes
268	 *
269	 ******************************************************************************/
270	static void bnep_congestion_ind(uint16_t l2cap_cid, bool is_congested) {
271	  tBNEP_CONN* p_bcb;
272	
273	  /* Find BCB based on CID */
274	  p_bcb = bnepu_find_bcb_by_cid(l2cap_cid);
275	  if (p_bcb == NULL) {
276	    BNEP_TRACE_WARNING("BNEP - Rcvd L2CAP cong, unknown CID: 0x%x", l2cap_cid);
277	    return;
278	  }
279	
280	  if (is_congested) {
281	    p_bcb->con_flags |= BNEP_FLAGS_L2CAP_CONGESTED;
282	    if (bnep_cb.p_tx_data_flow_cb) {
283	      bnep_cb.p_tx_data_flow_cb(p_bcb->handle, BNEP_TX_FLOW_OFF);
284	    }
285	  } else {
286	    p_bcb->con_flags &= ~BNEP_FLAGS_L2CAP_CONGESTED;
287	
288	    if (bnep_cb.p_tx_data_flow_cb) {
289	      bnep_cb.p_tx_data_flow_cb(p_bcb->handle, BNEP_TX_FLOW_ON);
290	    }
291	
292	    /* While not congested, send as many buffers as we can */
293	    while (!(p_bcb->con_flags & BNEP_FLAGS_L2CAP_CONGESTED)) {
294	      BT_HDR* p_buf = (BT_HDR*)fixed_queue_try_dequeue(p_bcb->xmit_q);
295	
296	      if (!p_buf) break;
297	
298	      L2CA_DataWrite(l2cap_cid, p_buf);
299	    }
300	  }
301	}
