303	/*******************************************************************************
304	 *
305	 * Function         bnep_data_ind
306	 *
307	 * Description      This function is called when data is received from L2CAP.
308	 *                  if we are the originator of the connection, we are the SDP
309	 *                  client, and the received message is queued for the client.
310	 *
311	 *                  If we are the destination of the connection, we are the SDP
312	 *                  server, so the message is passed to the server processing
313	 *                  function.
314	 *
315	 * Returns          void
316	 *
317	 ******************************************************************************/
318	static void bnep_data_ind(uint16_t l2cap_cid, BT_HDR* p_buf) {
319	  tBNEP_CONN* p_bcb;
320	  uint8_t* p = (uint8_t*)(p_buf + 1) + p_buf->offset;
321	  uint16_t rem_len = p_buf->len;
322	  if (rem_len == 0) {
323	    android_errorWriteLog(0x534e4554, "78286118");
324	    osi_free(p_buf);
325	    return;
326	  }
327	  uint8_t type, ctrl_type, ext_type = 0;
328	  bool extension_present, fw_ext_present;
329	  uint16_t protocol = 0;
330	
331	  /* Find CCB based on CID */
332	  p_bcb = bnepu_find_bcb_by_cid(l2cap_cid);
333	  if (p_bcb == NULL) {
334	    BNEP_TRACE_WARNING("BNEP - Rcvd L2CAP data, unknown CID: 0x%x", l2cap_cid);
335	    osi_free(p_buf);
336	    return;
337	  }
338	
339	  /* Get the type and extension bits */
340	  type = *p++;
341	  extension_present = type >> 7;
342	  type &= 0x7f;
343	  if (type >= sizeof(bnep_frame_hdr_sizes) / sizeof(bnep_frame_hdr_sizes[0])) {
344	    BNEP_TRACE_EVENT("BNEP - rcvd frame, bad type: 0x%02x", type);
345	    android_errorWriteLog(0x534e4554, "68818034");
346	    osi_free(p_buf);
347	    return;
348	  }
349	  if ((rem_len <= bnep_frame_hdr_sizes[type]) || (rem_len > BNEP_MTU_SIZE)) {
350	    BNEP_TRACE_EVENT("BNEP - rcvd frame, bad len: %d  type: 0x%02x", p_buf->len,
351	                     type);
352	    osi_free(p_buf);
353	    return;
354	  }
355	
356	  rem_len--;
357	
358	  if ((p_bcb->con_state != BNEP_STATE_CONNECTED) &&
359	      (!(p_bcb->con_flags & BNEP_FLAGS_CONN_COMPLETED)) &&
360	      (type != BNEP_FRAME_CONTROL)) {
361	    BNEP_TRACE_WARNING(
362	        "BNEP - Ignored L2CAP data while in state: %d, CID: 0x%x",
363	        p_bcb->con_state, l2cap_cid);
364	
365	    if (extension_present) {
366	      /*
367	      ** When there is no connection if a data packet is received
368	      ** with unknown control extension headers then those should be processed
369	      ** according to complain/ignore law
370	      */
371	      uint8_t ext, length;
372	      uint16_t org_len, new_len;
373	      /* parse the extension headers and process unknown control headers */
374	      org_len = rem_len;
375	      do {
376	        if (org_len < 2) {
377	          android_errorWriteLog(0x534e4554, "67863755");
378	          break;
379	        }
380	        ext = *p++;
381	        length = *p++;
382	
383	        new_len = (length + 2);
384	        if (new_len > org_len) {
385	          android_errorWriteLog(0x534e4554, "67863755");
386	          break;
387	        }
388	
389	        if ((ext & 0x7F) == BNEP_EXTENSION_FILTER_CONTROL) {
390	          if (length == 0) {
391	            android_errorWriteLog(0x534e4554, "79164722");
392	            break;
393	          }
394	          if (*p > BNEP_FILTER_MULTI_ADDR_RESPONSE_MSG) {
395	            bnep_send_command_not_understood(p_bcb, *p);
396	          }
397	        }
398	
399	        p += length;
400	
401	        org_len -= new_len;
402	      } while (ext & 0x80);
403	    }
404	    osi_free(p_buf);
405	    return;
406	  }
407	
408	  if (type > BNEP_FRAME_COMPRESSED_ETHERNET_DEST_ONLY) {
409	    BNEP_TRACE_EVENT("BNEP - rcvd frame, unknown type: 0x%02x", type);
410	    osi_free(p_buf);
411	    return;
412	  }
413	
414	  BNEP_TRACE_DEBUG("BNEP - rcv frame, type: %d len: %d Ext: %d", type,
415	                   p_buf->len, extension_present);
416	
417	  /* Initialize addresses to 'not supplied' */
418	  const RawAddress *p_src_addr, *p_dst_addr;
419	  p_src_addr = p_dst_addr = NULL;
420	
421	  switch (type) {
422	    case BNEP_FRAME_GENERAL_ETHERNET:
423	      p_dst_addr = (RawAddress*)p;
424	      p += BD_ADDR_LEN;
425	      p_src_addr = (RawAddress*)p;
426	      p += BD_ADDR_LEN;
427	      BE_STREAM_TO_UINT16(protocol, p);
428	      rem_len -= 14;
429	      break;
430	
431	    case BNEP_FRAME_CONTROL:
432	      ctrl_type = *p;
433	      p = bnep_process_control_packet(p_bcb, p, &rem_len, false);
434	
435	      if (ctrl_type == BNEP_SETUP_CONNECTION_REQUEST_MSG &&
436	          p_bcb->con_state != BNEP_STATE_CONNECTED && extension_present && p &&
437	          rem_len) {
438	        osi_free(p_bcb->p_pending_data);
439	        p_bcb->p_pending_data = (BT_HDR*)osi_malloc(rem_len + sizeof(BT_HDR));
440	        memcpy((uint8_t*)(p_bcb->p_pending_data + 1), p, rem_len);
441	        p_bcb->p_pending_data->len = rem_len;
442	        p_bcb->p_pending_data->offset = 0;
443	      } else {
444	        while (extension_present && p && rem_len) {
445	          ext_type = *p++;
446	          rem_len--;
447	          extension_present = ext_type >> 7;
448	          ext_type &= 0x7F;
449	
450	          /* if unknown extension present stop processing */
451	          if (ext_type != BNEP_EXTENSION_FILTER_CONTROL) break;
452	
453	          android_errorWriteLog(0x534e4554, "69271284");
454	          p = bnep_process_control_packet(p_bcb, p, &rem_len, true);
455	        }
456	      }
457	      osi_free(p_buf);
458	      return;
459	
460	    case BNEP_FRAME_COMPRESSED_ETHERNET:
461	      BE_STREAM_TO_UINT16(protocol, p);
462	      rem_len -= 2;
463	      break;
464	
465	    case BNEP_FRAME_COMPRESSED_ETHERNET_SRC_ONLY:
466	      p_src_addr = (RawAddress*)p;
467	      p += BD_ADDR_LEN;
468	      BE_STREAM_TO_UINT16(protocol, p);
469	      rem_len -= 8;
470	      break;
471	
472	    case BNEP_FRAME_COMPRESSED_ETHERNET_DEST_ONLY:
473	      p_dst_addr = (RawAddress*)p;
474	      p += BD_ADDR_LEN;
475	      BE_STREAM_TO_UINT16(protocol, p);
476	      rem_len -= 8;
477	      break;
478	  }
479	
480	  /* Process the header extension if there is one */
481	  while (extension_present && p && rem_len) {
482	    ext_type = *p;
483	    extension_present = ext_type >> 7;
484	    ext_type &= 0x7F;
485	
486	    /* if unknown extension present stop processing */
487	    if (ext_type) {
488	      BNEP_TRACE_EVENT("Data extension type 0x%x found", ext_type);
489	      break;
490	    }
491	
492	    p++;
493	    rem_len--;
494	    p = bnep_process_control_packet(p_bcb, p, &rem_len, true);
495	  }
496	
497	  p_buf->offset += p_buf->len - rem_len;
498	  p_buf->len = rem_len;
499	
500	  /* Always give the upper layer MAC addresses */
501	  if (!p_src_addr) p_src_addr = &p_bcb->rem_bda;
502	
503	  if (!p_dst_addr) p_dst_addr = controller_get_interface()->get_address();
504	
505	  /* check whether there are any extensions to be forwarded */
506	  if (ext_type)
507	    fw_ext_present = true;
508	  else
509	    fw_ext_present = false;
510	
511	  if (bnep_cb.p_data_buf_cb) {
512	    (*bnep_cb.p_data_buf_cb)(p_bcb->handle, *p_src_addr, *p_dst_addr, protocol,
513	                             p_buf, fw_ext_present);
514	  } else if (bnep_cb.p_data_ind_cb) {
515	    (*bnep_cb.p_data_ind_cb)(p_bcb->handle, *p_src_addr, *p_dst_addr, protocol,
516	                             p, rem_len, fw_ext_present);
517	    osi_free(p_buf);
518	  }
519	}
