521	/*******************************************************************************
522	 *
523	 * Function         bnep_conn_timer_timeout
524	 *
525	 * Description      This function processes a timeout. If it is a startup
526	 *                  timeout, we check for reading our BD address. If it
527	 *                  is an L2CAP timeout, we send a disconnect req to L2CAP.
528	 *
529	 * Returns          void
530	 *
531	 ******************************************************************************/
532	void bnep_conn_timer_timeout(void* data) {
533	  tBNEP_CONN* p_bcb = (tBNEP_CONN*)data;
534	
535	  BNEP_TRACE_EVENT(
536	      "BNEP - CCB timeout in state: %d  CID: 0x%x flags %x, re_transmit %d",
537	      p_bcb->con_state, p_bcb->l2cap_cid, p_bcb->con_flags,
538	      p_bcb->re_transmits);
539	
540	  if (p_bcb->con_state == BNEP_STATE_CONN_SETUP) {
541	    BNEP_TRACE_EVENT("BNEP - CCB timeout in state: %d  CID: 0x%x",
542	                     p_bcb->con_state, p_bcb->l2cap_cid);
543	
544	    if (!(p_bcb->con_flags & BNEP_FLAGS_IS_ORIG)) {
545	      L2CA_DisconnectReq(p_bcb->l2cap_cid);
546	
547	      bnepu_release_bcb(p_bcb);
548	      return;
549	    }
550	
551	    if (p_bcb->re_transmits++ != BNEP_MAX_RETRANSMITS) {
552	      bnep_send_conn_req(p_bcb);
553	      alarm_set_on_mloop(p_bcb->conn_timer, BNEP_CONN_TIMEOUT_MS,
554	                         bnep_conn_timer_timeout, p_bcb);
555	    } else {
556	      L2CA_DisconnectReq(p_bcb->l2cap_cid);
557	
558	      if ((p_bcb->con_flags & BNEP_FLAGS_IS_ORIG) && (bnep_cb.p_conn_state_cb))
559	        (*bnep_cb.p_conn_state_cb)(p_bcb->handle, p_bcb->rem_bda,
560	                                   BNEP_CONN_FAILED, false);
561	
562	      bnepu_release_bcb(p_bcb);
563	      return;
564	    }
565	  } else if (p_bcb->con_state != BNEP_STATE_CONNECTED) {
566	    BNEP_TRACE_EVENT("BNEP - CCB timeout in state: %d  CID: 0x%x",
567	                     p_bcb->con_state, p_bcb->l2cap_cid);
568	
569	    L2CA_DisconnectReq(p_bcb->l2cap_cid);
570	
571	    /* Tell the user if there is a callback */
572	    if ((p_bcb->con_flags & BNEP_FLAGS_IS_ORIG) && (bnep_cb.p_conn_state_cb))
573	      (*bnep_cb.p_conn_state_cb)(p_bcb->handle, p_bcb->rem_bda,
574	                                 BNEP_CONN_FAILED, false);
575	
576	    bnepu_release_bcb(p_bcb);
577	  } else if (p_bcb->con_flags & BNEP_FLAGS_FILTER_RESP_PEND) {
578	    if (p_bcb->re_transmits++ != BNEP_MAX_RETRANSMITS) {
579	      bnepu_send_peer_our_filters(p_bcb);
580	      alarm_set_on_mloop(p_bcb->conn_timer, BNEP_FILTER_SET_TIMEOUT_MS,
581	                         bnep_conn_timer_timeout, p_bcb);
582	    } else {
583	      L2CA_DisconnectReq(p_bcb->l2cap_cid);
584	
585	      /* Tell the user if there is a callback */
586	      if (bnep_cb.p_conn_state_cb)
587	        (*bnep_cb.p_conn_state_cb)(p_bcb->handle, p_bcb->rem_bda,
588	                                   BNEP_SET_FILTER_FAIL, false);
589	
590	      bnepu_release_bcb(p_bcb);
591	      return;
592	    }
593	  } else if (p_bcb->con_flags & BNEP_FLAGS_MULTI_RESP_PEND) {
594	    if (p_bcb->re_transmits++ != BNEP_MAX_RETRANSMITS) {
595	      bnepu_send_peer_our_multi_filters(p_bcb);
596	      alarm_set_on_mloop(p_bcb->conn_timer, BNEP_FILTER_SET_TIMEOUT_MS,
597	                         bnep_conn_timer_timeout, p_bcb);
598	    } else {
599	      L2CA_DisconnectReq(p_bcb->l2cap_cid);
600	
601	      /* Tell the user if there is a callback */
602	      if (bnep_cb.p_conn_state_cb)
603	        (*bnep_cb.p_conn_state_cb)(p_bcb->handle, p_bcb->rem_bda,
604	                                   BNEP_SET_FILTER_FAIL, false);
605	
606	      bnepu_release_bcb(p_bcb);
607	      return;
608	    }
609	  }
610	}
